"""Write docs/pqc_advisor_report.md for the image and video projects from the CBOM v2 entries and advisor data."""
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT / "src"))
sys.path.insert(0, str(ROOT / "scripts"))
import build_cbom_v2  # noqa: E402
import pqc_advisor    # noqa: E402


def fmt(v):
    return "not yet scored" if v is None else f"{v}"


def main():
    recs = pqc_advisor.load_recommendations()
    lines = ["# PQC advisor report", "",
             "Generated by scripts/advisor_report.py. ML-KEM, ML-DSA and AES-GCM are classical, quantum-resistant.",
             "Prototype libraries are educational and not production crypto.", ""]
    for project in build_cbom_v2.PROJECTS:
        doc = build_cbom_v2.build(project)
        lines += [f"## {project.capitalize()} project (pinned commit {build_cbom_v2.PROJECTS[project]['commit']})", ""]
        for e in doc["entries"]:
            r = recs[e["layer"]]
            sizes = ", ".join(f"{k}: {v:,} B" for k, v in r["sizes_bytes"].items()) or "n/a"
            lines += [f"### {e['layer']} {r['layer_name']}", "",
                      f"- Today: {e['component']}",
                      f"- Recommended: {r['technique']} ({r['standard']})",
                      f"- Sizes: {sizes}",
                      f"- Where to use it: {r['where_to_use']}",
                      f"- Why: {r['rationale']}",
                      f"- Trade-offs: {r['trade_offs']}"]
            if r.get("qkd_note"):
                lines.append(f"- QKD note: {r['qkd_note']}")
            lines += [f"- Risk now: {fmt(e['risk_percent'])} | after migration: {fmt(e['post_migration_risk_percent'])}", ""]
    out = ROOT / "docs" / "pqc_advisor_report.md"
    out.write_text("\n".join(lines), encoding="utf-8")
    print(f"wrote {out}")


if __name__ == "__main__":
    main()